const catalog = [
  { keywords: ['sql', 'database', 'postgres', 'postgresql'], course: 'Advanced PostgreSQL & Query Optimization', providers: ['Coursera', 'Udemy'], url: 'https://www.udemy.com/' },
  { keywords: ['cloud', 'docker', 'devops', 'kubernetes'], course: 'Docker & Kubernetes Cloud DevOps', providers: ['Coursera', 'Udemy'], url: 'https://www.udemy.com/' },
  { keywords: ['communication', 'leadership', 'teamwork', 'agile'], course: 'Agile Leadership and Team Coaching', providers: ['Coursera', 'LinkedIn Learning'], url: 'https://www.coursera.org/' },
  { keywords: ['python', 'ai', 'machine learning', 'data science', 'big data'], course: 'Python & AI Fundamentals', providers: ['Coursera', 'Udemy'], url: 'https://www.coursera.org/' }
];

return $input.all().map(({ json: r }) => {
  const skill = String(r.skill_name || '').toLowerCase();
  const match = catalog.find(c => c.keywords.some(k => skill.includes(k)));
  const gap = Math.max(0, Number(r.required_level || 0) - Number(r.current_level || 0));
  return {
    json: {
      ...r,
      skill_gap: gap,
      priority: gap >= 2 ? 'HIGH' : 'MEDIUM',
      recommended_course: match?.course || `Chuyên đề nâng cao: ${r.skill_name}`,
      providers: match?.providers || ['Coursera', 'Udemy'],
      course_url: match?.url || 'https://www.coursera.org/'
    }
  };
});
